import { AsyncLocalStorage } from 'node:async_hooks';
import * as http from 'node:http';
const als = new AsyncLocalStorage<string>();
function sleep(ms: number): Promise<number> { return new Promise<number>((r: (v: number) => void): void => { setTimeout((): void => { r(ms); }, ms); }); }
function main(): void {
  const srv = http.createServer((req: any, res: any): void => {
    const id = String(req.url).slice(1);
    als.run('req-' + id, async (): Promise<void> => {
      await sleep(id === 'a' ? 4 : 1);
      await sleep(1);
      res.setHeader('x-store', String(als.getStore()));
      res.end('ok');
    });
  });
  srv.listen(0, '127.0.0.1', (): void => {
    const port = (srv.address() as any).port;
    const out: string[] = [];
    for (const p of ['a', 'b']) {
      http.get({ host: '127.0.0.1', port, path: '/' + p }, (res: any): void => {
        res.on('data', (): void => {});
        res.on('end', (): void => {
          out.push(p + ':' + String(res.headers['x-store']));
          if (out.length === 2) { console.log(out.sort().join(',')); srv.close(); }
        });
      });
    }
  });
}
